<?php
namespace App\Http\Controllers; use App\Models\{User,PartnerProfile,VerificationReview}; use Illuminate\Http\Request;
class AdminController extends Controller { public function users(Request $r){$users=User::query()->when($r->role,fn($q)=>$q->where('role',$r->role))->when($r->status,fn($q)=>$q->where('account_status',$r->status))->when($r->search,fn($q)=>$q->where('full_name','like','%'.$r->search.'%'))->get(); return view('admin.users',compact('users'));} public function updateStatus(Request $r, User $user){$user->update($r->validate(['account_status'=>'required|in:ACTIVE,INACTIVE,SUSPENDED,DELETED'])); return back();} public function verifications(){return view('admin.verifications',['profiles'=>PartnerProfile::with('user','documents')->get()]);} public function review(Request $r, PartnerProfile $profile){$d=$r->validate(['decision'=>'required|in:APPROVED,REJECTED','remarks'=>'nullable']); $profile->update(['verification_status'=>$d['decision']]); VerificationReview::create(['partner_id'=>$profile->profile_id,'reviewed_by'=>auth()->id(),'decision'=>$d['decision'],'remarks'=>$d['remarks']??null]); return back();} }
